companion object {
private var instance: ChatListenersWrapper? = null
fun getInstance(): ChatListenersWrapper {
if (instance == null) {
synchronized(ChatListenersWrapper::class.java) {
if (instance == null) {
instance = ChatListenersWrapper()
}
}
}
return instance!!
}
