The BottomSheetMenu component provides menu functionality.
@example
```tsx
const ref = React.useRef<BizContextMenuRef>({} as any);
// ...
<BottomSheetMenu
ref={ref}
onRequestModalClose={() => {
ref.current.startHide();
}}
title={
'Nickname: Sei la cosa più bella che mia sia mai capitato non so stare senza te.'
}
initItems={data}
/>
```

The BottomSheetNameMenu component provides menu functionality.
Compared with `BottomSheetMenu`, it is simpler to use, you only need to enter a text array.
@example
```tsx
const menuRef = React.useRef<ContextNameMenuRef>({} as any);
// ...
<BottomSheetNameMenu
ref={menuRef}
initItems={[]}
onRequestModalClose={() => {
menuRef?.current?.startHide?.();
}}
/>
// ...
menuRef?.current?.startShowWithInit([
{
name: 'Mute',
isHigh: false,
onClicked: () => {
if (userId !== im.userId) {
muteMember(userId, true);
}
menuRef?.current?.startHide?.();
},
},
{
name: 'Remove',
isHigh: true,
onClicked: () => {
if (userId !== im.userId) {
removeMember(userId);
}
menuRef?.current?.startHide?.();
},
},
]);
```

